-- Exact reviewed current body, including private-document custody guards; no historical migration edit.
do $metadata$
declare patch jsonb := $patch${"signature":"public.save_instrument_profile(uuid,uuid,timestamptz,jsonb)","beforeSha256":"d1117f657411c66c6b079b21ad68033b4717a745c877440cce70a06f1bf00a81","afterSha256":"1c891ec2b7556f7cc0de457df89783d1e62c4c284bf0918d882242aabf6a7dfd","replacements":[{"before":"  item_id uuid;","after":"  item_id uuid;\n  spec_plan jsonb := '[]'::jsonb;\n  spec_next jsonb;\n  spec_reserved uuid[] := '{}';\n  spec_used uuid[] := '{}';\n  spec_count integer;\n  next_spec_sort integer;"},{"before":"builder = nullif(p_payload->'guitar'->>'builder', ''), location = nullif(p_payload->'guitar'->>'location', ''),","after":"builder = case when coalesce(guitar_row.builder,'')=coalesce(p_payload->'guitar'->>'builder','') then guitar_row.builder else nullif(p_payload->'guitar'->>'builder','') end, location = case when coalesce(guitar_row.location,'')=coalesce(p_payload->'guitar'->>'location','') then guitar_row.location else nullif(p_payload->'guitar'->>'location','') end,"},{"before":"  delete from public.guitar_specs where guitar_id = p_guitar_id;\n  for item in select value from jsonb_array_elements(p_payload->'specs') loop\n    if nullif(btrim(item->>'label'), '') is null or nullif(btrim(item->>'value'), '') is null then\n      raise exception using errcode = '22023', message = 'Invalid profile detail.';\n    end if;\n    insert into public.guitar_specs (guitar_id, label, value, sort_order)\n    values (p_guitar_id, item->>'label', item->>'value', (item->>'sort_order')::integer);\n  end loop;","after":"  -- Validate and reserve explicit identities before anonymous matching.\n  for item in select value from jsonb_array_elements(p_payload->'specs') loop\n    if jsonb_typeof(item) is distinct from 'object'\n       or jsonb_typeof(item->'label') is distinct from 'string'\n       or jsonb_typeof(item->'value') is distinct from 'string'\n       or nullif(btrim(item->>'label'), '') is null or nullif(btrim(item->>'value'), '') is null\n       or jsonb_typeof(item->'sort_order') is distinct from 'number'\n       or (item->>'sort_order') !~ '^[0-9]+$' then\n      raise exception using errcode = '22023', message = 'Invalid profile detail.';\n    end if;\n    item_id := null;\n    if item ? 'id' then\n      if jsonb_typeof(item->'id') is distinct from 'string' or (item->>'id') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then\n        raise exception using errcode = '22023', message = 'Invalid profile detail identity.';\n      end if;\n      item_id := (item->>'id')::uuid;\n      if item_id = any(spec_reserved) then\n        raise exception using errcode = '22023', message = 'A profile detail was submitted more than once.';\n      end if;\n      if not exists(select 1 from public.guitar_specs where id=item_id and guitar_id=p_guitar_id) then\n        raise exception using errcode = 'PT409', message = 'A profile detail changed. Reload this Profile.';\n      end if;\n      spec_reserved := array_append(spec_reserved,item_id);\n    end if;\n    spec_plan := spec_plan || jsonb_build_array(item || jsonb_build_object('id',item_id));\n  end loop;\n  spec_used := spec_reserved;\n  spec_next := '[]'::jsonb;\n  -- Match every unchanged duplicate first; reserve IDs so an edit cannot steal one.\n  for item in select value from jsonb_array_elements(spec_plan) loop\n    item_id := (item->>'id')::uuid;\n    if item_id is null then\n      select id into item_id from public.guitar_specs\n        where guitar_id=p_guitar_id and label=item->>'label' and value=item->>'value'\n          and not (id=any(spec_used)) order by sort_order,id limit 1;\n      if item_id is not null then spec_used:=array_append(spec_used,item_id);end if;\n    end if;\n    spec_next:=spec_next || jsonb_build_array(item || jsonb_build_object('id',item_id));\n  end loop;\n  spec_plan:=spec_next;\n  spec_next:='[]'::jsonb;\n  for item in select value from jsonb_array_elements(spec_plan) loop\n    item_id:=(item->>'id')::uuid;\n    if item_id is null then\n      select count(*) into spec_count from public.guitar_specs\n        where guitar_id=p_guitar_id and label=item->>'label' and not (id=any(spec_used));\n      if spec_count>1 then\n        raise exception using errcode='PT409',message='Duplicate profile details need explicit identities. Reload this Profile.';\n      elsif spec_count=1 then\n        select id into item_id from public.guitar_specs\n          where guitar_id=p_guitar_id and label=item->>'label' and not (id=any(spec_used));\n        spec_used:=array_append(spec_used,item_id);\n      else item_id:=gen_random_uuid();spec_used:=array_append(spec_used,item_id);\n      end if;\n    end if;\n    spec_next:=spec_next || jsonb_build_array(item || jsonb_build_object('id',item_id));\n  end loop;\n  select coalesce(max(sort_order),-1) into next_spec_sort from public.guitar_specs where guitar_id=p_guitar_id;\n  for item in select value from jsonb_array_elements(spec_next) loop\n    item_id:=(item->>'id')::uuid;\n    if exists(select 1 from public.guitar_specs where id=item_id and guitar_id=p_guitar_id) then\n      -- Full Save is not a separate detail-order operation. Keep legacy order and identity.\n      update public.guitar_specs set label=item->>'label',value=item->>'value'\n        where id=item_id and guitar_id=p_guitar_id\n          and (label is distinct from item->>'label' or value is distinct from item->>'value');\n    else\n      if next_spec_sort=2147483647 then raise exception using errcode='22023',message='Profile detail order is exhausted.';end if;\n      next_spec_sort:=next_spec_sort+1;\n      insert into public.guitar_specs(id,guitar_id,label,value,sort_order)\n        values(item_id,p_guitar_id,item->>'label',item->>'value',next_spec_sort);\n    end if;\n  end loop;\n  delete from public.guitar_specs where guitar_id=p_guitar_id\n    and not (id=any(array(select (value->>'id')::uuid from jsonb_array_elements(spec_next))));"}]}$patch$::jsonb;
  oid_value oid;old_body text;new_body text;definition text;edit jsonb;
begin
  oid_value:=to_regprocedure(patch->>'signature');
  if oid_value is null then raise exception 'Required Profile save function missing';end if;
  select replace(prosrc,E'\r\n',E'\n') into old_body from pg_proc where oid=oid_value;
  if encode(sha256(convert_to(old_body,'UTF8')),'hex')<>patch->>'beforeSha256' then raise exception 'Exact Profile save preimage differs';end if;
  new_body:=old_body;
  for edit in select value from jsonb_array_elements(patch->'replacements') loop
    if (length(new_body)-length(replace(new_body,edit->>'before','')))/length(edit->>'before')<>1 then raise exception 'Exact single Profile save anchor required';end if;
    new_body:=replace(new_body,edit->>'before',edit->>'after');
  end loop;
  if encode(sha256(convert_to(new_body,'UTF8')),'hex')<>patch->>'afterSha256' then raise exception 'Profile save postimage differs';end if;
  definition:=replace(pg_get_functiondef(oid_value),E'\r\n',E'\n');
  if (length(definition)-length(replace(definition,old_body,'')))/length(old_body)<>1 then raise exception 'Exact Profile save definition body required';end if;
  execute replace(definition,old_body,new_body);
end
$metadata$;
notify pgrst,'reload schema';
commit;
